/* ============================================================================
 * syscall.c -- System call dispatcher and implementations
 *
 * Handles INT 0x80 from user-mode code.
 * Syscall number in RAX, arguments in RDI, RSI, RDX.
 * Return value placed back in frame->rax.
 * ============================================================================ */

